const uid=()=>globalThis.crypto?.randomUUID?.()||Date.now().toString(36)+Math.random().toString(36).slice(2),fmt=n=>new Intl.NumberFormat('ru',{maximumFractionDigits:2}).format(n);
let state={recipes:structuredClone(seedRecipes),favorites:['signature','goulash','bolognese'],plan:[],pantry:[],extras:[],schedule:slots.map(s=>({...s})),reminders:false,timeZone:Intl.DateTimeFormat().resolvedOptions().timeZone||'Europe/Kaliningrad'},storageOK=true;
try{const saved=localStorage.getItem(key);if(saved){const p=JSON.parse(saved);if(p?.recipes&&p?.plan&&p?.pantry)state={...state,...p};}}catch{storageOK=false;}
