const icon=(name,size=20)=>`<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.spark}"/></svg>`;
const reelLayouts={"reel-syrniki": {"width": 1170, "height": 2532, "viewBox": "23 1076 983 722"}, "reel-pancake-bowl": {"width": 1170, "height": 2532, "viewBox": "0 1684 983 329"}, "reel-turkish-eggs": {"width": 1170, "height": 2532, "viewBox": "0 1076 1030 836"}, "reel-caesar": {"width": 1170, "height": 2532, "viewBox": "152 722 842 912"}, "reel-ribs": {"width": 1170, "height": 2532, "viewBox": "0 709 994 1089"}, "reel-paprika-chicken": {"width": 1170, "height": 2532, "viewBox": "0 1038 983 760"}, "reel-chicken-mushroom": {"width": 1170, "height": 2532, "viewBox": "0 696 1112 1013"}};
const photo=(r,w=900)=>r.image?.startsWith('reel-')?`./photos/${encodeURIComponent(r.image)}.jpg`:r.image?`https://images.unsplash.com/${encodeURIComponent(r.image)}?auto=format&fit=crop&w=${w}&q=85`:'';
const img=(r,cls='')=>{const layout=reelLayouts[r.image];if(layout)return `<div class="food-photo ${cls}"><svg class="reel-photo" viewBox="${layout.viewBox}" preserveAspectRatio="xMidYMid slice" aria-hidden="true"><image href="${photo(r)}" x="0" y="0" width="${layout.width}" height="${layout.height}"/></svg></div>`;return `<div class="food-photo ${cls}" style="${r.image?`background-image:url('${photo(r)}')`:''}">${!r.image?'<span class="food-fallback">🍽️</span>':''}</div>`;};

const isFav=r=>state.favorites.includes(r.id), catName=c=>({breakfast:'Завтрак',main:'Обед и ужин',snack:'Перекус'}[c]||c),dateLabel=d=>new Date(d+'T12:00:00').toLocaleDateString('ru',{day:'numeric',month:'long'}),dayLabel=d=>d===today()?'Сегодня':d===shift(today(),1)?'Завтра':new Date(d+'T12:00:00').toLocaleDateString('ru',{weekday:'long'});
function save(){try{localStorage.setItem(key,JSON.stringify(state));storageOK=true;}catch{storageOK=false;toast('Не удалось сохранить. Выгрузи резервную копию в настройках.');}if(telegramMode)queueCloudSave();}
let toastTimer;function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3300);}
function deck(){return state.recipes.filter(r=>(filter==='all'||r.category===filter)&&!passed.has(r.id));}
function favToggle(id){state.favorites=isFav({id})?state.favorites.filter(x=>x!==id):[...state.favorites,id];save();}
function render(){const d=deck(),current=d[index%d.length],planToday=state.plan.filter(p=>p.date===today()),missing=shopping(state.plan,state.recipes,state.pantry,today(),shift(today(),2));
$('#app').innerHTML=`<aside class="sidebar"><a class="brand" href="#" data-action="nav" data-tab="discover"><span class="brandmark">${icon('plate',26)}</span><span>есть идея<span class="brand-dot">.</span><small>ЕДА ПОД ТВОЙ РИТМ</small></span></a><div class="nav-caption">ТВОЯ КУХНЯ</div><nav>${[['discover','spark','Выбрать'],['plan','calendar','Меню'],['nutrition','plate','Дневник'],['shopping','box','Продукты']].map(([id,ic,name])=>`<button class="nav-item ${mainSection()===id?'active':''}" ${mainSection()===id?'aria-current="page"':''} data-action="nav" data-tab="${id}">${icon(ic)}<span>${name}</span></button>`).join('')}</nav><div class="sidebar-note"><div class="note-symbol">✳</div><strong>Меньше думать.<br>Вкуснее есть.</strong><p>Любимые блюда всегда<br>под рукой.</p></div><button class="nav-item settings" data-action="settings">${icon('settings')}<span>Настройки и копия</span></button><div class="profile"><span class="avatar">М</span><div><strong>Музаффар</strong><small>Моя коллекция еды</small></div><span class="online"></span></div></aside>
<div class="workspace" ${telegramMode&&cloud.status==='loading'?'inert':''}><header class="topbar"><span class="mobile-brand">есть идея<span>.</span></span><span class="breadcrumb">Моя кухня <span>/</span> ${{discover:'Что поесть',library:'Мои блюда',plan:'Меню',nutrition:'Дневник питания',shopping:'Покупки',pantry:'Продукты дома'}[tab]}</span><div class="top-actions"><span class="today-date">${dateLabel(today())}</span><button class="icon-btn" aria-label="Напоминания" data-action="settings">${icon('bell')}</button><button class="btn dark compact" data-action="add-recipe" aria-label="Добавить блюдо">${icon('plus',17)}<span>Добавить блюдо</span></button></div></header><main>${cloudBanner()}${window.EST_IDEYA_MIGRATION_NOTICE?`<div class="warning" role="status">${esc(window.EST_IDEYA_MIGRATION_NOTICE)}</div>`:''}${!storageOK?'<div class="warning">Сохранение в браузере недоступно. Сделай резервную копию в настройках перед выходом.</div>':''}${sectionNavigation()}${tab==='discover'?discover(current,d,planToday):tab==='library'?library():tab==='plan'?planView():tab==='shopping'?shoppingView():tab==='nutrition'?nutritionView():pantryView()}</main><footer>Собрано под твой вкус <span>✳</span> ${telegramMode?'Синхронизация через Telegram':'Локальная версия · открой через @mainreels_bot'}</footer></div>`;
bindSwipe();}
function heading(eyebrow,title,sub,action=''){return `<div class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${sub}</p></div>${action}</div>`;}
function discover(r,d,planned){return heading('ОДИН СВАЙП — И РЕШЕНО','Что будем есть<span class="serif">?</span>','Выбирай то, чего хочется. Остальное мы соберём в список.')+`<div class="discover-grid"><section class="picker"><div class="picker-bar"><div class="segmented meal-categories" aria-label="Приём пищи">${[['breakfast','Завтрак'],['main','Обед + ужин'],['snack','Перекус']].map(([id,n])=>`<button data-action="filter" data-filter="${id}" class="${filter===id?'selected':''}" aria-pressed="${filter===id}">${n}</button>`).join('')}</div><span class="counter">${d.length?index%d.length+1:0} / ${d.length}</span></div>${r?`<article class="hero-card ${spin?'spinning':''}" id="swipe-card" aria-label="Карточка блюда. Свайп вправо сохраняет, влево пропускает"><div class="swipe-label yes">ХОЧУ!</div><div class="swipe-label no">ПОТОМ</div>${img(r,'hero-photo')}<div class="photo-shade"></div><div class="hero-top"><span class="pill glass">${r.status==='tested'?'✓ Проверено тобой':'✳ Попробовать'}</span><button class="fav-button ${isFav(r)?'liked':''}" data-action="favorite" data-id="${r.id}" aria-label="${isFav(r)?'Убрать из':'Добавить в'} избранное">${icon('heart',22)}</button></div><div class="hero-copy"><div class="hero-tags"><span>${icon('clock',15)} ${r.time} мин</span><span>•</span><span>${catName(r.category)}</span>${r.batch?'<span>•</span><span>На несколько дней</span>':''}</div><h2>${esc(r.title)}</h2><p>${esc(r.desc)}</p><button class="text-link light" data-action="details" data-id="${r.id}">Рецепт и ингредиенты ${icon('arrow',17)}</button></div></article><div class="swipe-actions"><button class="round-action skip" data-action="pass" aria-label="Пропустить блюдо">${icon('close',25)}<span>Не сейчас</span></button><button class="btn plan-button" data-action="schedule" data-id="${r.id}">${icon('plus',19)} В меню</button><button class="round-action love" data-action="like-next" data-id="${r.id}" aria-label="Сохранить блюдо и перейти к следующему">${icon('heart',25)}<span>Хочу!</span></button></div><p class="swipe-hint">Свайпай карточку или выбирай кнопками</p>`:`<div class="empty deck-empty"><span>🍽️</span><h2>Все блюда просмотрены</h2><p>Вернём коллекцию или добавим что-то новое?</p><button class="btn dark" data-action="reset-deck">Посмотреть заново</button></div>`}<button class="roulette" data-action="roulette" ${!d.length?'disabled':''}><span class="roulette-icon">${icon('shuffle',24)}</span><span><strong>${spin?'Выбираем…':'Не могу выбрать'}</strong><small>Пусть решит рулетка</small></span>${icon('arrow',20)}</button></section><aside class="right-rail"><section class="day-card"><div class="section-top"><h3>Сегодня на столе</h3><span class="tiny-badge">${planned.length} ${planned.length===1?'блюдо':'блюд'}</span></div><p class="muted small">Хороший день начинается с плана.</p><div class="day-slots">${state.schedule.map(s=>{const p=planned.find(m=>m.slot===s.id),r=p&&state.recipes.find(r=>r.id===p.recipeId);return `<button class="day-slot" data-action="${r?'details':'slot-pick'}" ${r?`data-id="${r.id}"`:`data-slot="${s.id}"`}><span class="slot-emoji">${s.emoji}</span><span><small>${s.name} <i>${s.time}</i></small><strong class="${r?'':'unfilled'}">${r?esc(r.title):'Выбрать блюдо'}</strong></span>${icon(r&&p.cooked?'check':'plus',16)}</button>`;}).join('')}</div><button class="text-link" data-action="nav" data-tab="plan">Открыть меню ${icon('arrow',17)}</button></section><section class="green-note"><span class="little-spark">✳</span><span class="eyebrow">ТВОИ ФАВОРИТЫ</span><h3>Уже знаешь,<br>что любишь.</h3><p>Паста, гуляш и блюда с фаршем.<br>Собираем меню вокруг любимого.</p><button class="text-link" data-action="open-favorites">${state.favorites.length} в избранном ${icon('arrow',17)}</button></section><div class="quiet-note">${icon('box',18)}<p>Добавь продукты дома —<br>и покупай только недостающее.</p></div></aside></div>`;}
const categories=[{id:'breakfast',name:'Завтрак',emoji:'☀️',description:'Начать день с того, что нравится.'},{id:'main',name:'Обед + ужин',emoji:'🍝',description:'Сытные блюда и заготовки на несколько дней.'},{id:'snack',name:'Перекус',emoji:'🍓',description:'Быстро поесть между делами.'}];
const orderRecipes=list=>[...list].sort((a,b)=>(Number(b.status==='tested')-Number(a.status==='tested'))||a.title.localeCompare(b.title,'ru'));
function recipeTile(r){return `<article class="recipe-tile"><button class="tile-photo-button" data-action="details" data-id="${r.id}" aria-label="Открыть ${esc(r.title)}">${img(r)}<span class="pill white">${icon('clock',13)} ${r.time} мин</span></button><button class="tile-favorite ${isFav(r)?'liked':''}" data-action="favorite" data-id="${r.id}" aria-label="${isFav(r)?'Убрать из избранного':'В избранное'}">${icon('heart',19)}</button><div class="tile-body"><small>${r.status==='tested'?'✓ Проверено тобой':'✳ Попробовать'}</small><h3><button data-action="details" data-id="${r.id}">${esc(r.title)}</button></h3><p>${esc(r.desc)}</p>${nutritionLine(nutritionForRecipe(r))}<button class="text-link" data-action="schedule" data-id="${r.id}">В меню ${icon('plus',17)}</button></div></article>`;}
function library(){const cat=categories.find(c=>c.id===libraryCategory);const list=orderRecipes(state.recipes.filter(r=>r.category===libraryCategory&&(libraryFilter==='all'||libraryFilter==='favorite'&&isFav(r)||libraryFilter==='tested'&&r.status==='tested')&&(`${r.title} ${r.tags.join(' ')}`.toLocaleLowerCase('ru').includes(query.toLocaleLowerCase('ru')))));return heading('ТВОЯ КОЛЛЕКЦИЯ','Всё по своим местам<span class="serif">.</span>','Завтраки отдельно. Обеды и ужины вместе. Перекусы под рукой.')+`<div class="collection-categories" aria-label="Разделы блюд">${categories.map(c=>`<button data-action="library-category" data-category="${c.id}" class="category-tab ${libraryCategory===c.id?'selected':''}" aria-pressed="${libraryCategory===c.id}"><span class="category-emoji">${c.emoji}</span><span>${c.name}</span><b>${state.recipes.filter(r=>r.category===c.id).length}</b></button>`).join('')}</div><div class="library-toolbar"><label class="search">${icon('search')}<input id="search" placeholder="Найти в разделе…" value="${esc(query)}"></label><div class="segmented status-filters">${[['all','Все блюда'],['favorite','Избранное'],['tested','Проверено']].map(([id,n])=>`<button class="${libraryFilter===id?'selected':''}" data-action="library-filter" data-filter="${id}" aria-pressed="${libraryFilter===id}">${n}</button>`).join('')}</div></div><div class="category-heading"><div><h2>${cat.emoji} ${cat.name}</h2><p>${cat.description}</p></div><span>Сначала проверенные, затем А–Я</span></div><div class="recipe-grid">${list.map(recipeTile).join('')||'<div class="empty"><h3>Здесь пока пусто</h3><p>Измени фильтр или добавь блюдо в этот раздел.</p><button class="btn dark" data-action="add-recipe">Добавить блюдо</button></div>'}</div>`;}
function planView(){const meals=state.plan.filter(m=>m.date===date);return heading('ВКУСНЫЙ ПЛАН','Еда на каждый день<span class="serif">.</span>','Выбери блюда заранее, чтобы не пропустить обед.')+`<div class="date-navigation"><button class="icon-btn back" data-action="date-prev" aria-label="Предыдущий день">${icon('chevron')}</button><div><strong>${dayLabel(date)}, ${dateLabel(date)}</strong><input aria-label="Выбрать дату" id="plan-date" type="date" value="${date}"></div><button class="icon-btn" data-action="date-next" aria-label="Следующий день">${icon('chevron')}</button><button class="btn subtle" data-action="date-today">Сегодня</button></div><div class="plan-list">${state.schedule.map(s=>`<section class="plan-slot"><div class="plan-slot-heading"><span class="slot-emoji">${s.emoji}</span><div><h3>${s.name}</h3><span>${s.time}</span></div><button class="icon-btn" data-action="pick-for-slot" data-slot="${s.id}" aria-label="Добавить на ${s.name}">${icon('plus')}</button></div><div class="plan-meals">${meals.filter(m=>m.slot===s.id).map(m=>{const r=state.recipes.find(r=>r.id===m.recipeId);if(!r)return '';return `<article class="planned-meal ${m.cooked?'cooked':''}"><button class="planned-img" data-action="details" data-id="${r.id}">${img(r)}</button><div><button class="meal-title" data-action="details" data-id="${r.id}">${esc(r.title)}</button><p>${fmt(m.servings)} порц. <span>· ${r.time} мин</span></p><button class="btn ${m.cooked?'subtle':'dark'} compact" data-action="cook" data-id="${m.id}" ${m.cooked?'disabled':''}>${icon(m.cooked?'check':'plate',16)} ${m.cooked?'Приготовлено':'Приготовил'}</button></div><button class="btn subtle compact" data-action="meal-eaten" data-id="${m.id}" ${(state.foodLog||[]).some(x=>x.mealId===m.id)?'disabled':''}>${(state.foodLog||[]).some(x=>x.mealId===m.id)?'✓ Съедено':'Съел'}</button><button class="icon-btn" data-action="remove-meal" data-id="${m.id}" aria-label="Убрать из меню">${icon('close',17)}</button></article>`;}).join('')||`<button class="add-slot" data-action="pick-for-slot" data-slot="${s.id}">${icon('plus',18)} Что хочется на ${s.name.toLocaleLowerCase('ru')}?</button>`}</div></section>`).join('')}</div><div class="bottom-note">${icon('bag')}<span>Ингредиенты выбранных блюд уже учтены в покупках.</span><button class="text-link" data-action="nav" data-tab="shopping">К списку ${icon('arrow',16)}</button></div>`;}
function shoppingView(){const end=shift(date,range-1),list=shopping(state.plan,state.recipes,state.pantry,date,end);return heading('НИЧЕГО ЛИШНЕГО','Заглянем в магазин<span class="serif">?</span>','Ингредиенты из меню минус то, что уже есть дома.',`<button class="btn subtle" data-action="copy-shopping">${icon('download',17)} Скопировать список</button>`)+`<div class="range-bar"><label>С <input id="shop-date" type="date" value="${date}"></label><div class="segmented">${[1,3,7].map(n=>`<button class="${range===n?'selected':''}" data-action="range" data-value="${n}">${n===1?'На день':n===3?'На 3 дня':'На неделю'}</button>`).join('')}</div><span class="muted">до ${dateLabel(end)}</span></div><section class="list-card"><div class="section-top"><h3>Докупить <span class="count">${list.length+state.extras.length}</span></h3><span class="muted small">«Куплено» пополнит запасы</span></div>${list.length?list.map((i,n)=>`<div class="shopping-row"><button class="checkbox" data-action="buy" data-index="${n}" aria-label="Куплено: ${esc(i.name)}">${icon('check',14)}</button><span>${esc(i.name)}</span><strong>${fmt(i.qty)} ${esc(i.unit)}</strong><button class="text-link" data-action="buy" data-index="${n}">Куплено</button></div>`).join(''):`<div class="empty"><span>🧺</span><h3>${state.plan.some(m=>!m.cooked&&m.date>=date&&m.date<=end)?'Всё нужное уже дома':'Список пока пуст'}</h3><p>Добавь блюда в меню — недостающие продукты появятся здесь.</p><button class="btn subtle" data-action="nav" data-tab="plan">Составить меню</button></div>`}${state.extras.map((i,n)=>`<div class="shopping-row"><button class="checkbox" data-action="buy-extra" data-index="${n}" aria-label="Куплено: ${esc(i.name)}">${icon('check',14)}</button><span>${esc(i.name)} <small class="muted">вручную</small></span><strong>${fmt(i.qty)} ${esc(i.unit)}</strong><button class="icon-btn" data-action="remove-extra" data-index="${n}" aria-label="Удалить">${icon('close',16)}</button></div>`).join('')}<button class="add-line" data-action="extra">${icon('plus',18)} Добавить продукт вручную</button></section><p class="muted small">Количество рассчитано по выбранным порциям. Упаковки и фактический вес можно поправить в «Продуктах дома».</p>`;}
function pantryView(){return heading('ВСЁ ПОД КОНТРОЛЕМ','Что есть дома<span class="serif">.</span>','Добавляй покупки, меняй остатки и отмечай, что закончилось.',`<button class="btn dark" data-action="pantry-add">${icon('plus',18)} Добавить продукт</button>`)+`<section class="list-card"><div class="section-top"><h3>Мои запасы <span class="count">${state.pantry.length}</span></h3></div>${state.pantry.map((p,n)=>`<div class="pantry-row ${p.qty===0?'out':''}"><span class="pantry-emoji">${p.qty===0?'○':'◉'}</span><div><strong>${esc(p.name)}</strong><small>${p.qty===0?'Закончилось':'В наличии'}</small></div><b>${fmt(p.qty)} ${esc(p.unit)}</b><button class="icon-btn" data-action="pantry-edit" data-index="${n}" aria-label="Изменить ${esc(p.name)}">${icon('edit',17)}</button><button class="btn subtle compact" data-action="pantry-zero" data-index="${n}" ${p.qty===0?'disabled':''}>Закончилось</button><button class="icon-btn" data-action="pantry-delete" data-index="${n}" aria-label="Удалить ${esc(p.name)}">${icon('trash',17)}</button></div>`).join('')||'<div class="empty"><span>🥑</span><h3>Здесь будет твой холодильник</h3><p>Начни с продуктов, которые уже есть.<br>Покупки будут рассчитываться с учётом этих остатков.</p><button class="btn dark" data-action="pantry-add">Добавить первый продукт</button></div>'}</section><div class="bottom-note">${icon('plate')}<span>После кнопки «Приготовил» в меню ингредиенты спишутся из запасов.</span></div>`;}
function openModal(content,wide=false){if(telegramMode)tg.BackButton?.show();lastFocus=document.activeElement;$('#overlay').innerHTML=`<div class="modal-backdrop"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-label="${esc(modal?.label||'Окно блюда')}"><button class="modal-close icon-btn" data-action="close" aria-label="Закрыть">${icon('close')}</button>${content}</section></div>`;document.body.classList.add('modal-open');setTimeout(()=>$('#overlay').querySelector('input,select,button:not(.modal-close)')?.focus(),30);}
function closeModal(){if(telegramMode)tg.BackButton?.hide();modal=null;$('#overlay').innerHTML='';document.body.classList.remove('modal-open');lastFocus?.focus?.();}
function details(id){const r=state.recipes.find(x=>x.id===id);if(!r)return;modal={type:'details',id,label:r.title};openModal(`<div class="detail-photo">${img(r)}</div><div class="modal-content"><div class="eyebrow">${catName(r.category)} · ${r.time} МИНУТ</div><h2>${esc(r.title)}</h2><p class="muted">${esc(r.desc)}</p><div id="detail-nutrition">${nutritionLine(nutritionForRecipe(r))}</div><div class="detail-actions"><button class="btn subtle" data-action="food-add" data-id="${id}">Съел</button><button class="btn dark" data-action="schedule" data-id="${id}">${icon('plus',18)} В меню</button><button class="btn subtle" data-action="edit-recipe" data-id="${id}">${icon('edit',17)} Изменить</button><button class="btn subtle" data-action="tested" data-id="${id}">${icon('check',17)} ${r.status==='tested'?'Проверено тобой':'Отметить проверенным'}</button></div><div class="portion-control"><h3>Ингредиенты</h3><label>Порций <input id="detail-servings" type="number" min="0.25" max="100" step="0.25" value="1"></label></div><ul class="ingredient-list" id="detail-ingredients">${ingredientList(r,1)}</ul><h3>Как приготовить</h3><ol class="steps">${r.steps.map((s,i)=>`<li><span>${i+1}</span><p>${esc(s)}</p></li>`).join('')}</ol><div class="source-note"><strong>Заметка к рецепту</strong><p>${esc(r.source)}</p></div><div class="detail-foot"><span class="muted small">КБЖУ — на выбранное количество порций. Приблизительные значения можно уточнить в редакторе.</span><button class="text-link danger" data-action="delete-recipe" data-id="${id}">Удалить блюдо</button></div></div>`,true);}
const ingredientList=(r,n)=>r.ingredients.map(i=>`<li><span>${esc(i.name)}</span><b>${fmt(i.qty*n)} ${esc(i.unit)}</b></li>`).join('');
function schedule(id,slot){modal={type:'schedule',id,label:'Добавить блюдо в меню'};const r=state.recipes.find(r=>r.id===id);openModal(`<div class="modal-content"><div class="eyebrow">ВКУСНЫЙ ПЛАН</div><h2>Когда будем есть?</h2><p class="muted">${esc(r.title)}</p><form id="schedule-form"><label>Дата<input required type="date" name="date" value="${date}"></label><label>Приём пищи<select name="slot">${state.schedule.map(s=>`<option value="${s.id}" ${s.id===(slot||(r.category==='breakfast'?'breakfast':r.category==='snack'?'snack':'lunch'))?'selected':''}>${s.name} · ${s.time}</option>`).join('')}</select></label><label>Количество порций<input type="number" min="0.25" max="100" step="0.25" name="servings" value="1" required></label><button class="btn dark full" type="submit">Добавить в меню ${icon('arrow',18)}</button></form></div>`);}
function pick(slot){modal={type:'pick',slot,label:'Выбрать блюдо'};openModal(`<div class="modal-content"><div class="eyebrow">${state.schedule.find(s=>s.id===slot)?.name||'МЕНЮ'}</div><h2>Чего хочется?</h2><div class="pick-list">${orderRecipes(state.recipes.filter(r=>r.category===(slot==='breakfast'?'breakfast':slot==='snack'?'snack':'main'))).map(r=>`<button class="pick-row" data-action="pick-schedule" data-id="${r.id}" data-slot="${slot}">${img(r)}<span><strong>${esc(r.title)}</strong><small>${r.time} мин · ${catName(r.category)}</small></span>${icon('plus',17)}</button>`).join('')}</div></div>`);}
function productForm(kind,n){const p=kind==='pantry'&&n!==undefined?state.pantry[n]:null;modal={type:'product',kind,index:n,label:'Продукт'};const names=[...new Set(state.recipes.flatMap(r=>r.ingredients.map(i=>i.name)))].sort();openModal(`<div class="modal-content"><div class="eyebrow">${kind==='pantry'?'МОИ ЗАПАСЫ':'ПОКУПКИ'}</div><h2>${p?'Изменить остаток':'Добавить продукт'}</h2><form id="product-form"><label>Название<input name="name" list="product-names" required maxlength="100" value="${esc(p?.name||'')}" placeholder="Например, куриная грудка"></label><datalist id="product-names">${names.map(n=>`<option value="${esc(n)}">`).join('')}</datalist><p class="muted small">Выбери название из подсказок, чтобы продукт совпал с ингредиентами рецепта.</p><div class="form-row"><label>Количество<input type="number" name="qty" min="${p?'0':'0.1'}" max="1000000" step="any" required value="${p?.qty??''}"></label><label>Единица<select name="unit">${['г','мл','шт'].map(u=>`<option ${p?.unit===u?'selected':''}>${u}</option>`).join('')}</select></label></div><button class="btn dark full" type="submit">Сохранить</button></form></div>`);}
function recipeForm(id){const r=state.recipes.find(r=>r.id===id);modal={type:'recipe',id,label:r?'Изменить рецепт':'Новый рецепт'};openModal(`<div class="modal-content"><div class="eyebrow">ТВОЯ КОЛЛЕКЦИЯ</div><h2>${r?'Доведём до вкуса':'Новое любимое блюдо'}</h2><form id="recipe-form"><label>Название<input name="title" required maxlength="100" placeholder="Например, бабушкин гуляш" value="${esc(r?.title||'')}"></label><div class="form-row"><label>Категория<select name="category">${[['main','Обед и ужин'],['breakfast','Завтрак'],['snack','Перекус']].map(([v,n])=>`<option value="${v}" ${(r?.category||libraryCategory)===v?'selected':''}>${n}</option>`).join('')}</select></label><label>Время, минут<input name="time" type="number" min="1" max="1440" required value="${r?.time||20}"></label></div><label>Короткое описание<input name="desc" maxlength="300" value="${esc(r?.desc||'')}" placeholder="Что в нём особенно вкусного?"></label><label>Ингредиенты на одну порцию<textarea name="ingredients" rows="6" required placeholder="Куриная грудка | 200 | г&#10;Сливки без лактозы | 30 | мл">${esc(r?.ingredients.map(i=>`${i.name} | ${i.qty} | ${i.unit}`).join('\n')||'')}</textarea></label><p class="muted small">Один продукт в строке: название | количество | г, мл или шт. Крупы и пасту указывай сухими.</p>${nutritionFields(r?.nutrition)}<label>Шаги приготовления<textarea name="steps" rows="5" required placeholder="Каждый шаг — с новой строки">${esc(r?.steps.join('\n')||'')}</textarea></label><label>Источник или заметка<textarea name="source" rows="2" maxlength="2000" placeholder="Ссылка на рилс или твои уточнения">${esc(r?.source||'')}</textarea></label><label class="check-label"><input type="checkbox" name="tested" ${r?.status==='tested'?'checked':''}> Уже готовил, понравилось</label><p id="form-error" class="error" role="alert"></p><button class="btn dark full" type="submit">${r?'Сохранить изменения':'Добавить блюдо'}</button></form></div>`,true);}
function settings(){modal={type:'settings',label:'Настройки и резервная копия'};openModal(`<div class="modal-content"><div class="eyebrow">ПОД ТВОЙ РИТМ</div><h2>Настройки</h2><h3>Время приёмов пищи</h3><form id="settings-form"><div class="schedule-fields">${state.schedule.map(s=>`<label>${s.name}<input type="time" name="${s.id}" value="${s.time}" required></label>`).join('')}</div><label>Часовой пояс<input name="timeZone" value="${esc(state.timeZone||'Europe/Kaliningrad')}" placeholder="Europe/Kaliningrad" required></label><label class="check-label"><input type="checkbox" name="reminders" ${state.reminders?'checked':''}> Напоминать о еде</label><p class="muted small">${telegramMode?'Бот пришлёт сообщение в выбранное время, даже когда приложение закрыто. Сначала нажми /start в @mainreels_bot.':'В локальной версии напоминания работают только при открытом приложении. Для сообщений от бота открой приложение через @mainreels_bot.'}</p><button class="btn dark full" type="submit">Сохранить настройки</button></form><div class="settings-divider"></div>${telegramMode?'<button class="btn subtle full" data-action="inbox">Идеи из Telegram</button>':''}<h3>Твоя коллекция в сохранности</h3><p class="muted small">${telegramMode?'Меню, рецепты и остатки сохраняются в общей базе и доступны с устройств в твоём Telegram. Резервную копию можно выгрузить отдельно.':'Это локальная версия. Для синхронизации используй приложение внутри @mainreels_bot. Существующие данные можно перенести резервной копией.'}</p><div class="detail-actions"><button class="btn subtle" data-action="export">${icon('download',17)} Выгрузить копию</button><label class="btn subtle import-label">Загрузить копию<input id="import-file" type="file" accept="application/json,.json" hidden></label></div><p class="muted small">На iPhone открой приложение в Safari и выбери «Поделиться → На экран Домой». На Android — меню браузера → «Добавить на главный экран».</p><p class="muted small">Данные с упаковок можно внести в «Базу продуктов» в дневнике.</p></div>`);}
function cook(id){const m=state.plan.find(m=>m.id===id);if(!m||m.cooked)return;const r=state.recipes.find(r=>r.id===m.recipeId);const req=requirements([{...m,cooked:false}],state.recipes,m.date,m.date);const missing=req.filter(i=>(state.pantry.find(p=>p.key===i.key)?.qty||0)<i.qty);modal={type:'cook',id,label:'Приготовить и списать продукты'};openModal(`<div class="modal-content"><div class="eyebrow">ПРИЯТНОГО АППЕТИТА</div><h2>Блюдо готово?</h2><p>${esc(r.title)} · ${fmt(m.servings)} порц.</p><p class="muted">${missing.length?'В запасах не хватает некоторых ингредиентов. Можно списать только то, что учтено дома, и отметить блюдо готовым.':'Ингредиенты спишутся из запасов, а блюдо будет отмечено готовым.'}</p>${missing.length?`<ul class="ingredient-list">${missing.map(i=>`<li><span>${esc(i.name)}</span><b>не хватает ${fmt(i.qty-(state.pantry.find(p=>p.key===i.key)?.qty||0))} ${i.unit}</b></li>`).join('')}</ul>`:''}<button class="btn dark full" data-action="confirm-cook" data-id="${id}">${missing.length?'Списать имеющееся и отметить':'Списать продукты и отметить'}</button></div>`);}
function addPantry(i){const p=state.pantry.find(p=>p.key===i.key);if(p)p.qty=Math.round((p.qty+i.qty)*100)/100;else state.pantry.push({...i});}
function nextCard(like=false){const d=deck(),r=d[index%d.length];if(!r)return;if(like&&!isFav(r))state.favorites.push(r.id);passed.add(r.id);index=0;save();render();if(like)toast('Сохранено в избранное');}
document.addEventListener('click',async e=>{const el=e.target.closest('[data-action]');if(!el)return;const {action:a,id}=el.dataset;if(el.disabled)return;
if(a==='nav'){e.preventDefault();tab=el.dataset.tab;closeModal();render();window.scrollTo(0,0);}else if(a==='filter'){filter=el.dataset.filter;index=0;render();}else if(a==='favorite'){favToggle(id);render();}else if(a==='pass')nextCard();else if(a==='like-next')nextCard(true);else if(a==='reset-deck'){passed.clear();index=0;render();}else if(a==='roulette'){const d=deck();if(spin||!d.length)return;spin=true;let ticks=0;const prev=index;const t=setInterval(()=>{index=Math.floor(Math.random()*d.length);render();if(++ticks>=10){clearInterval(t);if(d.length>1&&index===prev)index=(index+1)%d.length;spin=false;render();toast('Есть идея! Смотри рецепт или добавляй в меню.');}},95);}else if(a==='details')details(id);else if(a==='schedule')schedule(id);else if(a==='slot-pick'){date=today();pick(el.dataset.slot);}else if(a==='pick-for-slot')pick(el.dataset.slot);else if(a==='pick-schedule')schedule(id,el.dataset.slot);else if(a==='close')closeModal();else if(a==='add-recipe')recipeForm();else if(a==='edit-recipe')recipeForm(id);else if(a==='tested'){const r=state.recipes.find(r=>r.id===id);r.status=r.status==='tested'?'try':'tested';save();render();details(id);}else if(a==='delete-recipe'){modal={type:'delete',id,label:'Удалить рецепт'};openModal(`<div class="modal-content"><h2>Удалить блюдо?</h2><p class="muted">Оно также исчезнет из меню. Остатки продуктов сохранятся.</p><button class="btn dark full" data-action="confirm-delete" data-id="${id}">Удалить блюдо</button></div>`);}else if(a==='confirm-delete'){state.recipes=state.recipes.filter(r=>r.id!==id);state.favorites=state.favorites.filter(x=>x!==id);state.plan=state.plan.filter(m=>m.recipeId!==id);save();closeModal();render();toast('Блюдо удалено');}else if(a==='open-favorites'){tab='library';libraryFilter='favorite';libraryCategory=state.recipes.find(r=>isFav(r))?.category||'breakfast';render();}else if(a==='library-category'){libraryCategory=el.dataset.category;query='';render();}else if(a==='library-filter'){libraryFilter=el.dataset.filter;render();}else if(a==='date-prev'||a==='date-next'){date=shift(date,a==='date-prev'?-1:1);render();}else if(a==='date-today'){date=today();render();}else if(a==='remove-meal'){state.plan=state.plan.filter(m=>m.id!==id);save();render();toast('Блюдо убрано из меню');}else if(a==='cook')cook(id);else if(a==='confirm-cook'){const m=state.plan.find(m=>m.id===id);if(m&&!m.cooked){for(const i of requirements([m],state.recipes,m.date,m.date)){const p=state.pantry.find(p=>p.key===i.key);if(p)p.qty=Math.max(0,Math.round((p.qty-i.qty)*100)/100);}m.cooked=true;save();}closeModal();render();toast('Готово! Запасы обновлены.');}else if(a==='range'){range=+el.dataset.value;render();}else if(a==='buy'){const i=shopping(state.plan,state.recipes,state.pantry,date,shift(date,range-1))[+el.dataset.index];if(i){addPantry(i);save();render();toast('Покупка добавлена в продукты дома');}}else if(a==='buy-extra'){const i=state.extras.splice(+el.dataset.index,1)[0];if(i){addPantry(i);save();render();toast('Добавлено в продукты дома');}}else if(a==='remove-extra'){state.extras.splice(+el.dataset.index,1);save();render();}else if(a==='extra')productForm('extra');else if(a==='pantry-add')productForm('pantry');else if(a==='pantry-edit')productForm('pantry',+el.dataset.index);else if(a==='pantry-zero'){state.pantry[+el.dataset.index].qty=0;save();render();toast('Продукт отмечен закончившимся');}else if(a==='pantry-delete'){state.pantry.splice(+el.dataset.index,1);save();render();}else if(a==='settings')settings();else if(a==='export'){const b=new Blob([JSON.stringify({version:1,exportedAt:new Date().toISOString(),state},null,2)],{type:'application/json'});const url=URL.createObjectURL(b),link=document.createElement('a');link.href=url;link.download=`est-ideya-${today()}.json`;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Резервная копия выгружена');}else if(a==='copy-shopping'){const list=shopping(state.plan,state.recipes,state.pantry,date,shift(date,range-1)).concat(state.extras);const text='Покупки · '+dateLabel(date)+'\n'+list.map(i=>`☐ ${i.name} — ${fmt(i.qty)} ${i.unit}`).join('\n');try{await navigator.clipboard.writeText(text);toast('Список скопирован');}catch{modal={type:'copy',label:'Список покупок'};openModal(`<div class="modal-content"><h2>Список покупок</h2><textarea rows="12" readonly>${esc(text)}</textarea><p>Выдели и скопируй текст.</p></div>`);}}
});
document.addEventListener('input',e=>{if(e.target.id==='search'){const pos=e.target.selectionStart;query=e.target.value;render();$('#search').focus();$('#search').setSelectionRange(pos,pos);}if(e.target.id==='detail-servings'&&modal?.type==='details'){const n=Number(e.target.value);if(n>0&&n<=100){const r=state.recipes.find(r=>r.id===modal.id);$('#detail-ingredients').innerHTML=ingredientList(r,n);$('#detail-nutrition').innerHTML=nutritionLine(scaleNutrition(nutritionForRecipe(r),n));}}});
document.addEventListener('change',async e=>{if(['plan-date','shop-date'].includes(e.target.id)&&e.target.value){date=e.target.value;render();}if(e.target.id==='import-file'){const file=e.target.files[0];if(!file)return;try{if(file.size>5e6)throw Error('Слишком большой файл');const p=JSON.parse(await file.text());validateImport(p);modal={type:'import',data:p.state,label:'Загрузить резервную копию'};openModal(`<div class="modal-content"><h2>Заменить текущие данные?</h2><p>В копии ${p.state.recipes.length} блюд и ${p.state.plan.length} записей меню. Текущие данные будут заменены.</p><button class="btn dark full" data-action="confirm-import">Загрузить эту копию</button></div>`);}catch{toast('Не удалось прочитать копию. Нужен корректный JSON из этого приложения.');e.target.value='';}}});
document.addEventListener('click',e=>{if(e.target.closest('[data-action="confirm-import"]')&&modal?.type==='import'){state={...state,...modal.data,schedule:slots.map(slot=>({...slot,time:modal.data.schedule.find(x=>x.id===slot.id).time}))};save();closeModal();passed.clear();index=0;render();toast('Резервная копия загружена');}if(e.target.classList.contains('modal-backdrop'))closeModal();});
document.addEventListener('submit',async e=>{if(!['schedule-form','product-form','recipe-form','settings-form'].includes(e.target.id))return;e.preventDefault();const f=new FormData(e.target);
if(e.target.id==='schedule-form'){state.plan.push({id:uid(),recipeId:modal.id,date:String(f.get('date')),slot:String(f.get('slot')),servings:Number(f.get('servings')),cooked:false});save();closeModal();render();toast('В меню! Список покупок обновлён.');}
if(e.target.id==='product-form'){const all=state.recipes.flatMap(r=>r.ingredients.map(i=>i.name)),raw=String(f.get('name')).trim(),name=all.find(n=>n.toLocaleLowerCase('ru')===raw.toLocaleLowerCase('ru'))||raw,unit=String(f.get('unit')),p={name,unit,qty:Number(f.get('qty')),key:name.toLocaleLowerCase('ru')+'|'+unit};if(!name||!Number.isFinite(p.qty)||p.qty<0)return;if(modal.kind==='pantry'){if(modal.index!==undefined){const old=state.pantry[modal.index];const duplicate=state.pantry.findIndex((x,n)=>x.key===p.key&&n!==modal.index);if(duplicate>=0){state.pantry[duplicate].qty+=p.qty;state.pantry.splice(modal.index,1);}else state.pantry[modal.index]=p;}else addPantry(p);}else state.extras.push(p);save();closeModal();render();toast('Продукт сохранён');}
if(e.target.id==='recipe-form'){const rows=String(f.get('ingredients')).split('\n').filter(s=>s.trim()).map(line=>{const parts=line.split('|').map(s=>s.trim());return{name:parts[0],qty:Number(parts[1]?.replace(',','.')),unit:parts[2],valid:parts.length===3};});if(!rows.length||rows.some(i=>!i.valid||!i.name||!Number.isFinite(i.qty)||i.qty<=0||!['г','мл','шт'].includes(i.unit))){$('#form-error').textContent='Проверь ингредиенты: название | положительное количество | г, мл или шт.';return;}const old=state.recipes.find(r=>r.id===modal.id),r={...(old||{}),id:old?.id||uid(),title:String(f.get('title')).trim(),desc:String(f.get('desc')).trim(),category:String(f.get('category')),time:Number(f.get('time')),ingredients:rows.map(({valid,...i})=>i),steps:String(f.get('steps')).split('\n').filter(s=>s.trim()),source:String(f.get('source')).trim()||'Твой рецепт.',status:f.has('tested')?'tested':'try',tags:old?.tags||[]};if(!r.title||!r.steps.length)return;const nutrition=readNutrition(f);if(nutrition==='invalid')return;if(nutrition)r.nutrition=nutrition;else delete r.nutrition;if(old)state.recipes[state.recipes.indexOf(old)]=r;else state.recipes.push(r);save();closeModal();render();toast('Рецепт сохранён в коллекции');}
if(e.target.id==='settings-form'){for(const s of state.schedule)s.time=String(f.get(s.id));const zone=String(f.get('timeZone')||'Europe/Kaliningrad');try{new Intl.DateTimeFormat('ru',{timeZone:zone}).format();}catch{toast('Проверь часовой пояс, например Europe/Kaliningrad');return;}state.timeZone=zone;state.reminders=f.has('reminders');save();if(!telegramMode&&state.reminders&&'Notification'in window&&Notification.permission==='default'){try{await Notification.requestPermission();}catch{}}closeModal();render();toast('Настройки сохранены');}});
function validateImport(p){const s=p?.state;if(s?.savedFoods!==undefined&&!validSavedFoods(s.savedFoods))throw Error();if(s?.foodLog!==undefined&&!validFoodLog(s.foodLog))throw Error();if(s?.calorieTarget!==undefined&&(!Number.isFinite(s.calorieTarget)||s.calorieTarget<1000||s.calorieTarget>6000))throw Error();if(Array.isArray(s?.recipes)&&s.recipes.some(r=>r.nutrition!==undefined&&!validNutrition(r.nutrition)))throw Error();if(p?.version!==1||!s||!Array.isArray(s.recipes)||!Array.isArray(s.plan)||!Array.isArray(s.pantry)||!Array.isArray(s.favorites)||!Array.isArray(s.extras)||!Array.isArray(s.schedule))throw Error();const ids=new Set();for(const r of s.recipes){if(typeof r.id!=='string'||ids.has(r.id)||typeof r.title!=='string'||typeof r.desc!=='string'||typeof r.source!=='string'||!['breakfast','main','snack'].includes(r.category)||!Number.isFinite(r.time)||r.time<1||!Array.isArray(r.tags)||!r.tags.every(t=>typeof t==='string')||!Array.isArray(r.ingredients)||!Array.isArray(r.steps)||!r.steps.every(t=>typeof t==='string')||r.image&&!/^(?:photo-[a-zA-Z0-9-]+|reel-[a-z0-9-]+)$/.test(r.image))throw Error();ids.add(r.id);for(const i of r.ingredients)if(typeof i.name!=='string'||!Number.isFinite(i.qty)||i.qty<=0||!['г','мл','шт'].includes(i.unit))throw Error();}if(s.schedule.length!==4||!slots.every(slot=>s.schedule.filter(x=>x.id===slot.id).length===1)||!s.schedule.every(x=>typeof x.name==='string'&&typeof x.emoji==='string'&&/^([01]\d|2[0-3]):[0-5]\d$/.test(x.time)))throw Error();for(const i of [...s.pantry,...s.extras])if(typeof i.name!=='string'||!['г','мл','шт'].includes(i.unit)||!Number.isFinite(i.qty)||i.qty<0||i.key!==i.name.toLocaleLowerCase('ru')+'|'+i.unit)throw Error();for(const m of s.plan)if(typeof m.id!=='string'||!ids.has(m.recipeId)||!/^\d{4}-\d{2}-\d{2}$/.test(m.date)||!slots.some(x=>x.id===m.slot)||!Number.isFinite(m.servings)||m.servings<=0||m.servings>100||typeof m.cooked!=='boolean')throw Error();if(!s.favorites.every(id=>typeof id==='string'&&ids.has(id)))throw Error();}
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();if(e.key==='Tab'&&modal){const focusables=[...$('#overlay').querySelectorAll('button:not([disabled]),input:not([hidden]),select,textarea,a[href]')].filter(x=>x.offsetParent!==null);const first=focusables[0],last=focusables.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}});
function bindSwipe(){const c=$('#swipe-card');if(!c)return;let start=null;c.addEventListener('pointerdown',e=>{if(e.target.closest('button'))return;start={x:e.clientX,y:e.clientY};});c.addEventListener('pointermove',e=>{if(!start)return;const x=e.clientX-start.x;if(Math.abs(x)<Math.abs(e.clientY-start.y))return;swipeX=x;c.style.transform=`translateX(${x*.35}px) rotate(${x*.025}deg)`;c.querySelector('.yes').style.opacity=x>30?Math.min(1,x/100):0;c.querySelector('.no').style.opacity=x< -30?Math.min(1,-x/100):0;});const end=()=>{if(!start)return;start=null;if(Math.abs(swipeX)>90)nextCard(swipeX>0);else{c.style.transform='';c.querySelectorAll('.swipe-label').forEach(x=>x.style.opacity=0);}swipeX=0;};c.addEventListener('pointerup',end);c.addEventListener('pointercancel',()=>{start=null;swipeX=0;c.style.transform='';});c.addEventListener('pointerleave',end);}
const notified=new Set();setInterval(()=>{if(telegramMode||!state.reminders)return;const now=new Date(),time=`${String(now.getHours()).padStart(2,'0')}:${String(now.getMinutes()).padStart(2,'0')}`;for(const s of state.schedule){const k=today()+s.id;if(s.time!==time||notified.has(k))continue;notified.add(k);const text=`Пора на ${s.name.toLowerCase()} — выбери что-нибудь вкусное.`;toast(text);if('Notification'in window&&Notification.permission==='granted')try{new Notification('Есть идея', {body:text,icon:'/favicon.svg'});}catch{}}},15000);
let cloud={status:telegramMode?'loading':'local',revision:null,saving:false,dirty:false,timer:null,message:''};
function cloudBanner(){if(!telegramMode)return '';const status=cloud.status;return `<div class="cloud-status ${['error','conflict'].includes(status)?'cloud-warning':''}" role="status"><span>${status==='loading'?'Подключаем твою кухню…':status==='saving'?'Сохраняем…':status==='conflict'?'Данные изменились на другом устройстве. Твоя копия сохранена локально.':status==='error'?esc(cloud.message||'Нет связи. Изменения пока только на этом устройстве.'):status==='migration'?'Есть локальная коллекция. Можно перенести её в Telegram.':'✓ Сохранено в твоём Telegram'}</span>${['error','conflict'].includes(status)?'<button data-action="export">Выгрузить копию</button><button data-action="cloud-retry">Повторить сохранение</button><button data-action="cloud-reload">Загрузить из базы</button>':status==='migration'?'<button data-action="cloud-import-local">Перенести мою коллекцию</button>':''}</div>`;}
async function api(path,options={}){const res=await fetch((window.EST_IDEYA_API_BASE||'')+path,{...options,headers:{'Content-Type':'application/json','X-Telegram-Init-Data':tg.initData,...options.headers}});if(!res.ok){const e=Error(res.status===409?'conflict':res.status===401?'Сессия истекла. Закрой и снова открой приложение из бота.':res.status===403?'Этот бот настроен на другой Telegram ID.':res.status===503?'Бот ещё не подключён к базе.':`Ошибка сохранения (${res.status})`);e.status=res.status;throw e;}return res.json();}
function queueCloudSave(){cloud.dirty=true;if(cloud.revision===null||cloud.status==='conflict')return;clearTimeout(cloud.timer);cloud.timer=setTimeout(flushCloudSave,350);}
async function flushCloudSave(){if(!telegramMode||cloud.saving||cloud.revision===null||cloud.status==='conflict'||!cloud.dirty)return;cloud.saving=true;cloud.dirty=false;cloud.status='saving';render();const snapshot=JSON.parse(JSON.stringify(state));try{const result=await api('/api/state',{method:'PUT',body:JSON.stringify({state:snapshot,revision:cloud.revision})});cloud.revision=result.revision;cloud.status='ready';}catch(e){cloud.dirty=true;cloud.status=e.status===409?'conflict':'error';cloud.message=e.message;}finally{cloud.saving=false;render();if(cloud.dirty&&cloud.status==='ready')queueCloudSave();}}
async function connectCloud(){if(!telegramMode)return;try{const current=await api('/api/state');validateImport({version:1,state:current.state});cloud.revision=current.revision;cloud.dirty=false;if(current.revision===0&&localStorage.getItem(key)){cloud.status='migration';}else{state=current.state;try{localStorage.setItem(key,JSON.stringify(state));}catch{}cloud.status='ready';}render();}catch(e){cloud.status='error';cloud.message=e.message;render();}}
async function openInbox(){try{const result=await api('/api/inbox');modal={type:'inbox',items:result.items,label:'Идеи из Telegram'};openModal(`<div class="modal-content"><div class="eyebrow">ИЗ ТВОЕГО БОТА</div><h2>Идеи из Telegram</h2><p class="muted">Отправляй @mainreels_bot ссылки, текст и фото рецептов. Здесь они ждут разбора.</p>${result.items.map(i=>`<article class="inbox-note"><p>${esc(i.text)}</p>${i.has_photo?'<small>К заметке прикреплено фото в переписке с ботом.</small>':''}<button class="btn subtle" data-action="inbox-recipe" data-id="${i.id}">Оформить рецепт</button></article>`).join('')||'<div class="empty"><p>Пока пусто. Пришли боту первый рецепт.</p></div>'}</div>`);}catch(e){toast(e.message);}}
document.addEventListener('click',async e=>{const el=e.target.closest('[data-action]');if(!el)return;const a=el.dataset.action;if(a==='cloud-retry'){if(cloud.revision===null)await connectCloud();else if(cloud.status!=='conflict'){cloud.status='ready';cloud.dirty=true;await flushCloudSave();}else toast('Сначала выгрузи копию и загрузи общую версию.');}if(a==='inbox')await openInbox();if(a==='inbox-recipe'){const note=modal?.items?.find(x=>x.id===Number(el.dataset.id));if(note){recipeForm();$('#recipe-form [name="source"]').value=note.text;}}if(a==='cloud-import-local'){cloud.status='ready';queueCloudSave();render();}if(a==='cloud-reload'){modal={type:'cloud-reload',label:'Загрузить данные из базы'};openModal('<div class="modal-content"><h2>Загрузить общую версию?</h2><p class="muted">Локальные изменения будут заменены. Сначала выгрузи копию, если хочешь их сохранить.</p><button class="btn subtle full" data-action="export">Выгрузить копию</button><button class="btn dark full" data-action="cloud-reload-confirm">Загрузить из базы</button></div>');}if(a==='cloud-reload-confirm'){closeModal();cloud.status='loading';cloud.revision=null;try{const current=await api('/api/state');validateImport({version:1,state:current.state});state=current.state;cloud.revision=current.revision;cloud.dirty=false;cloud.status='ready';try{localStorage.setItem(key,JSON.stringify(state));}catch{}}catch(e){cloud.status='error';cloud.message=e.message;}render();}});
if(telegramMode){tg.ready();tg.expand();tg.setHeaderColor?.('#f6f5ef');tg.setBackgroundColor?.('#f6f5ef');tg.BackButton?.onClick(closeModal);document.body.classList.add('telegram-app');}
render();connectCloud();

function nutritionLine(n){return n?`<p class="nutrition-line">${n.estimated?'≈ ':''}<strong>${Math.round(n.kcal)} ккал</strong> · Б ${n.protein===null?'—':fmt(n.protein)} · Ж ${n.fat===null?'—':fmt(n.fat)} · У ${n.carbs===null?'—':fmt(n.carbs)} г${n.estimated?' <small>оценка</small>':''}</p>`:'<p class="muted small">КБЖУ пока не указаны — можно добавить в редакторе.</p>';}
function nutritionFields(n){return `<fieldset class="nutrition-fields"><legend>КБЖУ на одну порцию</legend><p class="muted small">Необязательно. Пустые поля — расчёт по известным ингредиентам. Для точного значения используй этикетки; белки, жиры и углеводы можно оставить неизвестными.</p><div class="macro-inputs">${[['kcal','Ккал'],['protein','Белки, г'],['fat','Жиры, г'],['carbs','Углеводы, г']].map(([k,label])=>`<label>${label}<input name="${k}" type="number" min="0" max="${k==='kcal'?20000:2000}" step="any" value="${n?.[k]??''}" placeholder="Не указано"></label>`).join('')}</div><label class="check-label"><input name="estimated" type="checkbox" ${n?.estimated!==false?'checked':''}> Приблизительные значения</label></fieldset>`;}
function readNutrition(f){const values=['kcal','protein','fat','carbs'].map(k=>String(f.get(k)??'').trim());if(values.every(x=>x===''))return null;const n=Object.fromEntries(['kcal','protein','fat','carbs'].map((k,i)=>[k,values[i]===''?null:Number(values[i])]));n.estimated=f.has('estimated');if(!validNutrition(n)){toast('Укажи калории. КБЖУ должны быть неотрицательными числами.');return 'invalid';}return n;}
function nutritionView(){const entries=(state.foodLog||[]).filter(x=>x.date===date),actual=sumNutrition(entries.map(x=>scaleNutrition(x.nutrition,x.servings))),planned=sumNutrition(state.plan.filter(m=>m.date===date).map(m=>scaleNutrition(nutritionForRecipe(state.recipes.find(r=>r.id===m.recipeId)),m.servings))),target=state.calorieTarget||2900;return heading('ЕДА И ЭНЕРГИЯ','Дневник питания<span class="serif">.</span>','Записывай то, что съел. Перекусы, кофе и сладости тоже считаются.',`<button class="btn dark" data-action="food-add">${icon('plus',18)} Добавить еду</button><button class="btn subtle" data-action="product-db">База продуктов</button>`)+`<div class="date-navigation"><button class="icon-btn" data-action="date-prev" aria-label="Предыдущий день">‹</button><div><strong>${dateLabel(date)}</strong><input type="date" id="plan-date" aria-label="Дата дневника" value="${date}"></div><button class="icon-btn" data-action="date-next" aria-label="Следующий день">›</button><button class="btn subtle" data-action="date-today">Сегодня</button></div><section class="energy-card"><span class="eyebrow">СЪЕДЕНО ЗА ДЕНЬ · ОЦЕНКА</span><h2>${Math.round(actual.kcal)} <small>/ ${target} ккал</small></h2><progress max="${target}" value="${Math.min(actual.kcal,target)}" aria-label="Калории за день"></progress><p>Белки ${fmt(actual.protein)} г · жиры ${fmt(actual.fat)} г · углеводы ${fmt(actual.carbs)} г</p>${actual.unknown||actual.partial?'<p class="error">Итог неполный: у части записей не заполнены калории или БЖУ.</p>':''}<p class="muted">В меню запланировано: ${Math.round(planned.kcal)} ккал${planned.unknown?' + блюда без КБЖУ':''}. Это отдельный ориентир, он не прибавляется к съеденному.</p><button class="text-link" data-action="calorie-goal">Изменить цель</button></section><section class="list-card"><h3>Что съел</h3>${entries.map(x=>`<article class="food-entry"><div><strong>${esc(x.name)}</strong><small>${fmt(x.servings)} порц.</small>${nutritionLine(scaleNutrition(x.nutrition,x.servings))}</div><button class="icon-btn" data-action="food-delete" data-id="${esc(x.id)}" aria-label="Убрать запись ${esc(x.name)}">${icon('trash',18)}</button></article>`).join('')||'<div class="empty"><p>Пока нет записей. Нажми «Съел» у блюда в меню или добавь еду вручную.</p></div>'}</section><p class="nutrition-note">Расчёт рецептов приблизительный: сливки приняты 20%, творог 5%, молоко 2,5%, фарш около 15% жира, яйцо — около 50 г без скорлупы. Бренды и масло при готовке меняют итог. Неизвестные ингредиенты не считаются нулём. Цель 2 900 ккал — стартовый ориентир, его можно менять по динамике веса.</p>`;}
function rememberedFoods(){const list=[...(state.savedFoods||[])],seen=new Set(list.map(x=>x.name.trim().toLocaleLowerCase('ru'))),recipeNames=new Set(state.recipes.map(x=>x.title.toLocaleLowerCase('ru')));for(const x of [...(state.foodLog||[])].reverse()){const key=x.name.trim().toLocaleLowerCase('ru');const baseKey=key.replace(/ \([\d\s,.]+ г\/мл\)$/,'');if(seen.has(baseKey))continue;if(!x.nutrition||recipeNames.has(key)||seen.has(key))continue;seen.add(key);list.push({id:'history:'+x.id,name:x.name,basis:'portion',nutrition:x.nutrition});}return list;}
function foodPicker(){modal={type:'food-picker',label:'Выбрать еду'};const saved=rememberedFoods();openModal(`<div class="modal-content"><div class="eyebrow">ДНЕВНИК ПИТАНИЯ</div><h2>Что съел?</h2><button class="btn dark full" data-action="food-new">${icon('plus',18)} Новый продукт или перекус</button><button class="btn subtle full" data-action="product-db">База продуктов · КБЖУ на 100 г</button><h3>Сохранённая еда</h3><p class="muted small">Один раз укажи КБЖУ — потом выбирай из списка. Еда из прошлых записей тоже здесь.</p><div class="pick-list">${saved.map(x=>`<button class="pick-row" data-action="food-saved" data-id="${esc(x.id)}"><span><strong>${esc(x.name)}</strong><small>${Math.round(x.nutrition.kcal)} ккал / ${x.basis==='100'?'100 г или мл':'порция'}</small></span>${icon('plus',18)}</button>`).join('')||'<p class="muted small">Пока пусто. Новый перекус запомнится после первой записи.</p>'}</div><h3>Мои блюда</h3><div class="pick-list">${orderRecipes(state.recipes).map(r=>`<button class="pick-row" data-action="food-add" data-id="${r.id}">${img(r)}<span><strong>${esc(r.title)}</strong><small>${catName(r.category)} · ${nutritionForRecipe(r)?Math.round(nutritionForRecipe(r).kcal)+' ккал / порция':'КБЖУ пока не указаны'}</small></span>${icon('plus',18)}</button>`).join('')}</div></div>`);}
function foodForm(id,mealId,savedId){const r=state.recipes.find(x=>x.id===id),meal=state.plan.find(x=>x.id===mealId),saved=rememberedFoods().find(x=>x.id===savedId),known=r||saved,base=r?nutritionForRecipe(r):saved?.nutrition;modal={type:'food',id,mealId,savedId,label:'Записать съеденное'};openModal(`<div class="modal-content"><div class="eyebrow">ДНЕВНИК ПИТАНИЯ</div><h2>${known?'Записать съеденное':'Перекус или другая еда'}</h2><form id="food-form"><label>Дата<input required name="date" type="date" value="${meal?.date||date}"></label>${known?`<h3>${esc(known.title||known.name)}</h3>${nutritionLine(base)}<p class="muted small">Значения выше — ${saved?.basis==='100'?'на 100 г или 100 мл':'на одну порцию'}. Количество можно указать дробным.</p><label>${saved?.basis==='100'?'Сколько съел, '+(saved.unit||'г/мл'):'Сколько порций съел'}<input required type="number" inputmode="decimal" name="servings" min="0.01" max="${saved?.basis==='100'?10000:100}" step="any" value="${saved?.basis==='100'?100:meal?.servings||1}"></label>`:`<label>Название<input required name="name" maxlength="100" placeholder="Например, банан или капучино"></label><label>Значения указаны<select name="basis"><option value="portion">На одну порцию (например, один банан)</option><option value="100">На 100 г или 100 мл</option></select></label><label>Сколько порций съел<input name="servings" type="number" inputmode="decimal" min="0.01" max="100" step="any" value="1"></label><label>Съеденный вес / объём, если значения на 100<input name="amount" type="number" inputmode="decimal" min="0.1" max="10000" step="any" value="100"></label>${nutritionFields(null)}<label class="check-label"><input type="checkbox" name="remember" checked> Запомнить еду и КБЖУ для следующего раза</label>`}<p class="muted small">Запись учитывает только съеденное. Запасы и приготовление отмечаются отдельно в меню.</p><button class="btn dark full" type="submit">Записать в дневник</button></form></div>`);}
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el||el.disabled)return;const {action,id}=el.dataset;if(action==='food-add'){if(id)foodForm(id);else foodPicker();}if(action==='food-new')foodForm();if(action==='food-saved')foodForm(undefined,undefined,id);if(action==='meal-eaten'){const m=state.plan.find(x=>x.id===id);if(m&&!(state.foodLog||[]).some(x=>x.mealId===id))foodForm(m.recipeId,id);}if(action==='food-delete'){state.foodLog=(state.foodLog||[]).filter(x=>x.id!==id);save();render();toast('Запись убрана из дневника');}if(action==='calorie-goal'){modal={type:'goal',label:'Цель по калориям'};openModal(`<div class="modal-content"><h2>Дневная цель</h2><form id="goal-form"><label>Ккал в день<input required name="target" type="number" min="1000" max="6000" step="50" value="${state.calorieTarget||2900}"></label><button class="btn dark full">Сохранить</button></form></div>`);}});
document.addEventListener('submit',e=>{if(!['food-form','goal-form'].includes(e.target.id))return;e.preventDefault();const f=new FormData(e.target);if(e.target.id==='goal-form'){const target=Number(f.get('target'));if(!Number.isFinite(target)||target<1000||target>6000)return;state.calorieTarget=target;save();closeModal();render();return;}if(modal?.type!=='food')return;const r=state.recipes.find(x=>x.id===modal.id),saved=rememberedFoods().find(x=>x.id===modal.savedId),known=r||saved;let n=r?nutritionForRecipe(r):saved?saved.nutrition:readNutrition(f);if(n==='invalid')return;if(!known&&!n){toast('Укажи хотя бы калории с упаковки или свою оценку');return;}let name=r?.title||saved?.name||String(f.get('name')).trim(),servings=Number(String(f.get('servings')||'1').replace(',','.'));const entryDate=String(f.get('date')),basis=saved?.basis||String(f.get('basis')||'portion'),originalNutrition=n;if(!name||!Number.isFinite(servings)||servings<=0||!/^\d{4}-\d{2}-\d{2}$/.test(entryDate))return;if(basis==='100'){const amount=saved?servings:Number(String(f.get('amount')).replace(',','.'));if(!Number.isFinite(amount)||amount<=0||amount>10000)return;n=scaleNutrition(n,amount/100);name=`${name} (${fmt(amount)} ${saved?.unit||'г/мл'})`.slice(0,100);servings=1;}if(servings>100)return;if(modal.mealId&&(state.foodLog||[]).some(x=>x.mealId===modal.mealId)){closeModal();return;}if(n&&!validNutrition(n)){toast('Слишком большое значение КБЖУ. Проверь вес и этикетку.');return;}if(!known&&f.has('remember')){state.savedFoods??=[];const baseName=String(f.get('name')).trim(),old=state.savedFoods.find(x=>x.name.toLocaleLowerCase('ru')===baseName.toLocaleLowerCase('ru')&&x.basis===basis);const entry={id:old?.id||uid(),name:baseName,basis,nutrition:originalNutrition};if(old)state.savedFoods[state.savedFoods.indexOf(old)]=entry;else state.savedFoods.push(entry);}state.foodLog??=[];state.foodLog.push({id:uid(),name,date:entryDate,servings,nutrition:n, ...(modal.mealId?{mealId:modal.mealId}:{})});save();closeModal();render();toast('Съеденное записано');});

function nutritionForRecipe(r){return recipeNutrition(r,state.savedFoods||[]);}
function productDatabase(){modal={type:'products',label:'База продуктов'};const list=(state.savedFoods||[]).filter(x=>x.basis==='100');openModal(`<div class="modal-content"><div class="eyebrow">ДАННЫЕ С УПАКОВКИ</div><h2>База продуктов</h2><p class="muted">Внеси КБЖУ один раз. При записи еды укажешь только вес. Сохранение продукта не добавляет его в дневник и не меняет запасы.</p><button class="btn dark full" data-action="catalog-new">Добавить продукт</button>${list.map(p=>`<article class="catalog-product"><h3>${esc(p.name)}</h3><p class="muted small">На 100 ${p.unit||'г'}${p.ingredientName?' · В рецептах: '+esc(p.ingredientName):''}</p>${nutritionLine(p.nutrition)}<div class="detail-actions"><button class="btn dark" data-action="food-saved" data-id="${esc(p.id)}">Съел</button><button class="btn subtle" data-action="catalog-edit" data-id="${esc(p.id)}">Изменить</button><button class="text-link danger" data-action="catalog-delete" data-id="${esc(p.id)}">Удалить</button></div></article>`).join('')||'<div class="empty"><p>Например: молоко определённой марки, шоколад или твой йогурт.</p></div>'}<p class="muted small">Уже съеденные порции сохраняют свои КБЖУ: изменение упаковки не переписывает историю.</p></div>`);}
function catalogForm(id){const p=(state.savedFoods||[]).find(x=>x.id===id),names=[...new Set(state.recipes.flatMap(r=>r.ingredients.map(i=>i.name)))].sort((a,b)=>a.localeCompare(b,'ru'));modal={type:'catalog',id,label:'Продукт и КБЖУ'};openModal(`<div class="modal-content"><h2>${p?'Изменить продукт':'Новый продукт'}</h2><form id="catalog-form"><label>Название и марка<input name="name" required maxlength="100" value="${esc(p?.name||'')}" placeholder="Йогурт, марка, жирность"></label><label>Данные на 100<select name="unit"><option value="г" ${p?.unit!=='мл'?'selected':''}>граммов</option><option value="мл" ${p?.unit==='мл'?'selected':''}>миллилитров</option></select></label><div class="macro-inputs">${[['kcal','Ккал'],['protein','Белки, г'],['fat','Жиры, г'],['carbs','Углеводы, г']].map(([k,n])=>`<label>${n}<input required type="number" inputmode="decimal" name="${k}" min="0" max="${k==='kcal'?20000:2000}" step="any" value="${p?.nutrition[k]??''}"></label>`).join('')}</div><label>Использовать для ингредиента в рецептах<select name="ingredientName"><option value="">По точному названию продукта</option>${names.map(n=>`<option value="${esc(n)}" ${p?.ingredientName===n?'selected':''}>${esc(n)}</option>`).join('')}</select></label><p class="muted small">Например, выбери «Сыр», чтобы рецепты считались по твоей пачке сыра. Для граммов и миллилитров используются только совпадающие единицы. Ручные КБЖУ целого рецепта остаются приоритетными.</p><button class="btn dark full" type="submit">Сохранить продукт</button></form></div>`);}
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el||el.disabled)return;const {action,id}=el.dataset;if(action==='product-db')productDatabase();if(action==='catalog-new')catalogForm();if(action==='catalog-edit')catalogForm(id);if(action==='catalog-delete'){modal={type:'catalog-delete',id,label:'Удалить продукт'};openModal(`<div class="modal-content"><h2>Удалить продукт из базы?</h2><p class="muted">Записи о съеденном сохранятся. Расчёт будущих блюд снова будет использовать оставшиеся данные.</p><button class="btn dark full" data-action="catalog-confirm-delete" data-id="${esc(id)}">Удалить продукт</button></div>`);}if(action==='catalog-confirm-delete'){state.savedFoods=(state.savedFoods||[]).filter(x=>x.id!==id);save();productDatabase();render();}});
document.addEventListener('submit',e=>{if(e.target.id!=='catalog-form')return;e.preventDefault();const f=new FormData(e.target),name=String(f.get('name')).trim(),ingredientName=String(f.get('ingredientName')||''),unit=String(f.get('unit')),nutrition=Object.fromEntries(['kcal','protein','fat','carbs'].map(k=>[k,Number(String(f.get(k)).replace(',','.'))]));nutrition.estimated=false;if(!name||!validNutrition(nutrition))return;const key=(ingredientName||name).toLocaleLowerCase('ru'),list=state.savedFoods||[];if(list.some(x=>x.id!==modal.id&&x.basis==='100'&&(x.unit||'г')===unit&&(x.ingredientName||x.name).toLocaleLowerCase('ru')===key)){toast('Такой продукт или привязка уже есть. Измени существующую запись.');return;}const p={id:modal.id||uid(),name,basis:'100',unit,nutrition,...(ingredientName?{ingredientName}:{})};state.savedFoods??=[];const index=state.savedFoods.findIndex(x=>x.id===modal.id);if(index>=0)state.savedFoods[index]=p;else state.savedFoods.push(p);save();productDatabase();render();toast('Продукт сохранён. Расчёт новых порций обновлён.');});

function mainSection(){return tab==='library'?'discover':tab==='pantry'?'shopping':tab;}
function sectionNavigation(){if(['discover','library'].includes(tab))return `<div class="section-navigation" role="group" aria-label="Разделы выбора еды">${[['discover','Подбор'],['library','Все блюда']].map(([id,name])=>`<button data-action="nav" data-tab="${id}" aria-pressed="${tab===id}" class="${tab===id?'selected':''}">${name}</button>`).join('')}</div>`;if(['shopping','pantry'].includes(tab))return `<div class="section-navigation" role="group" aria-label="Разделы продуктов"><button data-action="nav" data-tab="shopping" aria-pressed="${tab==='shopping'}" class="${tab==='shopping'?'selected':''}">Покупки</button><button data-action="nav" data-tab="pantry" aria-pressed="${tab==='pantry'}" class="${tab==='pantry'?'selected':''}">Дома</button><button data-action="product-db">База КБЖУ</button></div>`;return '';}
